import{_ as n,o as s,c as a,a2 as i}from"./chunks/framework.CPzUcv0I.js";const h=JSON.parse('{"title":"Native Gens-Core Modules (Zero Dependencies)","description":"","frontmatter":{},"headers":[],"relativePath":"guide/dev/native-modules.md","filePath":"guide/dev/native-modules.md"}'),o={name:"guide/dev/native-modules.md"};function t(r,e,c,l,d,p){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="native-gens-core-modules-zero-dependencies" tabindex="-1">Native Gens-Core Modules (Zero Dependencies) <a class="header-anchor" href="#native-gens-core-modules-zero-dependencies" aria-label="Permalink to &quot;Native Gens-Core Modules (Zero Dependencies)&quot;">​</a></h1><div style="display:flex;gap:8px;margin:1rem 0;flex-wrap:wrap;"><img src="https://img.shields.io/badge/Dependencies-0%25%20Bloatware-green.svg" alt="Dependencies"><img src="https://img.shields.io/badge/Modules-100%25%20In--House-blue.svg" alt="Modules"><img src="https://img.shields.io/badge/Security-Minimal%20Attack%20Surface-orange.svg" alt="Security"></div><p>To drastically minimize package size, accelerate cold boot times, and eliminate vulnerabilities arising from dependency supply chains, Gens-Launcher avoids heavy third-party npm packages in favor of <strong>100% native in-house modules</strong>.</p><hr><h2 id="_1-native-discord-rich-presence-discord-js" tabindex="-1">1. Native Discord Rich Presence (<code>discord.js</code>) <a class="header-anchor" href="#_1-native-discord-rich-presence-discord-js" aria-label="Permalink to &quot;1. Native Discord Rich Presence (\`discord.js\`)&quot;">​</a></h2><p>Rather than relying on <code>@xhayper/discord-rpc</code> or the official Discord GameSDK (which introduce heavy binary bloat and multiple sub-dependencies), Gens-Launcher implements its own RPC client using operating system <strong>Named Pipes</strong>:</p><ul><li><strong>Low-Level Protocol:</strong><ul><li><strong>Windows:</strong> Direct stream connection to <code>\\\\?\\pipe\\discord-ipc-0</code>.</li><li><strong>Linux / macOS:</strong> Unix domain socket connection to <code>$XDG_RUNTIME_DIR/discord-ipc-0</code> or <code>/tmp/discord-ipc-0</code>.</li></ul></li><li><strong>Binary Frame Parser:</strong> Handcrafted encoder and decoder for Discord IPC opcodes (<code>HANDSHAKE = 0</code>, <code>FRAME = 1</code>, <code>CLOSE = 2</code>, <code>PING = 3</code>, <code>PONG = 4</code>) leveraging Node.js Buffers.</li><li><strong>Integrated Rate Limiter:</strong> Protects against rate limits on presence updates.</li><li><strong>Smart Offline Management:</strong> When running without an active network connection, <code>discord.js</code> reads <code>settings.json</code> locally and defuses recurring connection retries to prevent zombie sockets.</li></ul><hr><h2 id="_2-binary-nbt-parser-and-builder-nbt-js" tabindex="-1">2. Binary NBT Parser and Builder (<code>nbt.js</code>) <a class="header-anchor" href="#_2-binary-nbt-parser-and-builder-nbt-js" aria-label="Permalink to &quot;2. Binary NBT Parser and Builder (\`nbt.js\`)&quot;">​</a></h2><p>The Named Binary Tag (NBT) format is the standard binary serialization used by Minecraft for world saves, entity data, and player server lists (<code>servers.dat</code>).</p><p>Gens-Launcher replaces <code>prismarine-nbt</code> with a lightweight, native implementation built upon <code>node:zlib</code>:</p><ul><li><strong>Compression Support:</strong> Automatic GZIP/ZLIB decompression header detection and uncompressed stream processing.</li><li><strong>Full Tag Specification:</strong> TAG_End (0), TAG_Byte (1), TAG_Short (2), TAG_Int (3), TAG_Long (4), TAG_Float (5), TAG_Double (6), TAG_Byte_Array (7), TAG_String (8), TAG_List (9), TAG_Compound (10), TAG_Int_Array (11), TAG_Long_Array (12).</li><li><strong>Native BigInt Support:</strong> Preserves 64-bit integer precision for world seeds and epoch timestamps.</li><li><strong>Safe Server List Operations:</strong> Enables the launcher UI to reorder and add multiplayer servers directly into <code>servers.dat</code> without risking file corruption.</li></ul><hr><h2 id="_3-in-house-microsoft-authentication-flow-auth-js" tabindex="-1">3. In-House Microsoft Authentication Flow (<code>auth.js</code>) <a class="header-anchor" href="#_3-in-house-microsoft-authentication-flow-auth-js" aria-label="Permalink to &quot;3. In-House Microsoft Authentication Flow (\`auth.js\`)&quot;">​</a></h2><p>The Microsoft and Xbox Live login chain is implemented from scratch:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ Step 1: Device Code Acquisition ]</span></span>
<span class="line"><span>POST https://login.microsoftonline.com/consumers/oauth2/v2.0/devicecode</span></span>
<span class="line"><span>  -&gt; Returns user_code and verification_uri</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[ Step 2: OAuth2 Token Polling ]</span></span>
<span class="line"><span>POST https://login.microsoftonline.com/consumers/oauth2/v2.0/token</span></span>
<span class="line"><span>  -&gt; Exchanges device code for refresh_token and access_token</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[ Step 3: Xbox Live (XBL) Authentication ]</span></span>
<span class="line"><span>POST https://user.auth.xboxlive.com/user/authenticate</span></span>
<span class="line"><span>  -&gt; Exchanges access_token for XBL token and UserHash</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[ Step 4: XSTS Authorization (Minecraft Scope) ]</span></span>
<span class="line"><span>POST https://xsts.auth.xboxlive.com/xsts/authorize</span></span>
<span class="line"><span>  -&gt; Exchanges XBL token for XSTS token</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[ Step 5: Minecraft Access Token ]</span></span>
<span class="line"><span>POST https://api.minecraftservices.com/authentication/login_with_xbox</span></span>
<span class="line"><span>  -&gt; Yields official Minecraft bearer token</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[ Step 6: Player Profile &amp; UUID ]</span></span>
<span class="line"><span>GET https://api.minecraftservices.com/minecraft/profile</span></span>
<span class="line"><span>  -&gt; Retrieves player UUID, username, skin textures, and capes</span></span></code></pre></div><ul><li><strong>TLS Security:</strong> All communication strictly enforces HTTPS with standard certificate authority verification.</li><li><strong>Silent Background Refresh:</strong> Stored encrypted refresh tokens automatically refresh expired bearer tokens without interrupting gameplay.</li></ul><hr><h2 id="_4-minecraft-launch-engine-src-gens-core-components-launcher-js" tabindex="-1">4. Minecraft Launch Engine (<code>src/gens-core/components/launcher.js</code>) <a class="header-anchor" href="#_4-minecraft-launch-engine-src-gens-core-components-launcher-js" aria-label="Permalink to &quot;4. Minecraft Launch Engine (\`src/gens-core/components/launcher.js\`)&quot;">​</a></h2><p>Handles preparation and execution of the Minecraft Java process:</p><ul><li><strong>Checksum Verification:</strong> Every jar library and asset index file is validated against its official SHA-1 hash.</li><li><strong>Classpath Assembly:</strong> Dynamically constructs the <code>-cp</code> argument using OS-specific path separators (<code>;</code> on Windows, <code>:</code> on Unix).</li><li><strong>Native Extraction:</strong> Extracts platform-specific <code>.dll</code>, <code>.so</code>, or <code>.dylib</code> archives into an isolated temporary folder purged upon termination.</li><li><strong>Safe Process Invocation:</strong> Uses <code>child_process.execFile</code> instead of <code>child_process.exec</code>, preventing shell injection vulnerabilities.</li></ul>`,21)])])}const g=n(o,[["render",t]]);export{h as __pageData,g as default};
